file.content:
:root {
  --text: #6b6375;
  --text-h: #08060d;
  --bg: #fff;
  --border: #e5e4e7;
  --code-bg: #f4f3ec;
  --accent: #aa3bff;
  --accent-bg: rgba(170, 59, 255, 0.1);
  --accent-border: rgba(170, 59, 255, 0.5);
  --social-bg: rgba(244, 243, 236, 0.5);
  --shadow:
    rgba(0, 0, 0, 0.1) 0 10px 15px -3px, rgba(0, 0, 0, 0.05) 0 4px 6px -2px;

  --sans: system-ui, 'Segoe UI', Roboto, sans-serif;
  --heading: system-ui, 'Segoe UI', Roboto, sans-serif;
  --mono: ui-monospace, Consolas, monospace;

  font: 18px/145% var(--sans);
  letter-spacing: 0.18px;
  color-scheme: light dark;
  color: var(--text);
  background: var(--bg);
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;

  @media (max-width: 1024px) {
    font-size: 16px;
  }
}

@media (prefers-color-scheme: dark) {
  :root {
    --text: #9ca3af;
    --text-h: #f3f4f6;
    --bg: #16171d;
    --border: #2e303a;
    --code-bg: #1f2028;
    --accent: #c084fc;
    --accent-bg: rgba(192, 132, 252, 0.15);
    --accent-border: rgba(192, 132, 252, 0.5);
    --social-bg: rgba(47, 48, 58, 0.5);
    --shadow:
      rgba(0, 0, 0, 0.4) 0 10px 15px -3px, rgba(0, 0, 0, 0.25) 0 4px 6px -2px;
  }

  #social .button-icon {
    filter: invert(1) brightness(2);
  }
}

#root {
  width: 1126px;
  max-width: 100%;
  margin: 0 auto;
  text-align: center;
  border-inline: 1px solid var(--border);
  min-height: 100svh;
  display: flex;
  flex-direction: column;
  box-sizing: border-box;
}

body {
  margin: 0;
}

h1,
h2 {
  font-family: var(--heading);
  font-weight: 500;
  color: var(--text-h);
}

h1 {
  font-size: 56px;
  letter-spacing: -1.68px;
  margin: 32px 0;
  @media (max-width: 1024px) {
    font-size: 36px;
    margin: 20px 0;
  }
}
h2 {
  font-size: 24px;
  line-height: 118%;
  letter-spacing: -0.24px;
  margin: 0 0 8px;
  @media (max-width: 1024px) {
    font-size: 20px;
  }
}
p {
  margin: 0;
}

code,
.counter {
  font-family: var(--mono);
  display: inline-flex;
  border-radius: 4px;
  color: var(--text-h);
}

code {
  font-size: 15px;
  line-height: 135%;
  padding: 4px 8px;
  background: var(--code-bg);
}

input.content:
@import "tailwindcss";
@import "maplibre-gl/dist/maplibre-gl.css";

@theme {
  --font-sans: -apple-system, "Segoe UI", Inter, Roboto, sans-serif;
  --font-serif: ui-serif, "Iowan Old Style", Georgia, "Times New Roman", serif;
  --font-mono: ui-monospace, "SF Mono", "Cascadia Code", Consolas, monospace;

  /* Ink / paper — a calm, dark survey-instrument palette */
  --color-ink-950: #0c0d10;
  --color-ink-900: #121317;
  --color-ink-850: #16181d;
  --color-ink-800: #1c1e25;
  --color-ink-700: #262933;
  --color-ink-600: #343846;
  --color-ink-500: #4a4f60;
  --color-ink-400: #6b7086;
  --color-ink-300: #9298ab;
  --color-ink-200: #c2c6d4;
  --color-ink-100: #e4e6ec;
  --color-ink-50: #f4f5f8;

  --color-paper: #f4f2ec;

  /* Semantic accents */
  --color-shallow: #e2725b;
  --color-intermediate: #d9a441;
  --color-deep: #4f7cac;

  --color-alert-green: #4f9d69;
  --color-alert-yellow: #d9b02a;
  --color-alert-orange: #d9791f;
  --color-alert-red: #c94c3f;

  --color-accent: #d9a441;
  --color-accent-soft: #d9a44133;
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
}

body {
  margin: 0;
  background: var(--color-ink-950);
  color: var(--color-ink-100);
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  background-image:
    radial-gradient(circle at 1px 1px, rgba(255, 255, 255, 0.035) 1px, transparent 0);
  background-size: 22px 22px;
}

:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
  border-radius: 2px;
}

::selection {
  background: var(--color-accent-soft);
}

/* tabular figures for anything numeric */
.tnum {
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum";
}

.contour-divider {
  background-image: repeating-linear-gradient(
    to right,
    var(--color-ink-700) 0,
    var(--color-ink-700) 4px,
    transparent 4px,
    transparent 9px
  );
  height: 1px;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }
}

@keyframes pulse-ring {
  0% {
    opacity: 0.55;
    transform: scale(0.9);
  }
  100% {
    opacity: 0;
    transform: scale(1.9);
  }
}

.pulse-ring {
  animation: pulse-ring 2.2s ease-out infinite;
}

/* MapLibre attribution/control chrome, restyled to match the instrument palette */
.maplibregl-ctrl-attrib {
  background: rgba(12, 13, 16, 0.72) !important;
  color: var(--color-ink-300) !important;
  font-size: 10.5px !important;
}
.maplibregl-ctrl-attrib a {
  color: var(--color-ink-200) !important;
}
.maplibregl-ctrl-group {
  background: var(--color-ink-850) !important;
  border: 1px solid var(--color-ink-700) !important;
  box-shadow: none !important;
}
.maplibregl-ctrl-group button {
  background: transparent !important;
}
.maplibregl-ctrl-group button + button {
  border-top: 1px solid var(--color-ink-700) !important;
}
.maplibregl-ctrl-group button:hover {
  background: var(--color-ink-800) !important;
}
.maplibregl-popup-content {
  background: var(--color-ink-850) !important;
  color: var(--color-ink-100) !important;
  border: 1px solid var(--color-ink-700) !important;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4) !important;
  border-radius: 10px !important;
  font-family: var(--font-sans) !important;
}
.maplibregl-popup-tip {
  display: none !important;
}
.maplibregl-popup-close-button {
  color: var(--color-ink-300) !important;
  font-size: 16px !important;
  padding: 4px 8px !important;
}

