import type {
  EarthquakeEvent,
  TimeRangeKey,
  TimeRangeOption,
  UsgsFeedCollection,
} from "../types/earthquake";

export const TIME_RANGES: TimeRangeOption[] = [
  {
    key: "hour",
    label: "Past hour",
    shortLabel: "1h",
    feedUrl: "https://earthquake.usgs.gov/earthquakes/feed/v1.0/summary/all_hour.geojson",
    description: "Every located event in the last 60 minutes.",
  },
  {
    key: "day",
    label: "Past day",
    shortLabel: "24h",
    feedUrl: "https://earthquake.usgs.gov/earthquakes/feed/v1.0/summary/all_day.geojson",
    description: "Every located event in the last 24 hours.",
  },
  {
    key: "week",
    label: "Past 7 days",
    shortLabel: "7d",
    feedUrl: "https://earthquake.usgs.gov/earthquakes/feed/v1.0/summary/all_week.geojson",
    description: "Every located event in the last 7 days.",
  },
  {
    key: "month",
    label: "Past 30 days",
    shortLabel: "30d",
    feedUrl: "https://earthquake.usgs.gov/earthquakes/feed/v1.0/summary/all_month.geojson",
    description: "Every located event in the last 30 days.",
  },
];

export function getTimeRange(key: TimeRangeKey): TimeRangeOption {
  return TIME_RANGES.find((r) => r.key === key) ?? TIME_RANGES[2];
}

export class UsgsFetchError extends Error {
  constructor(
    message: string,
    public readonly cause?: unknown,
  ) {
    super(message);
    this.name = "UsgsFetchError";
  }
}

export async function fetchEarthquakeFeed(
  url: string,
  signal?: AbortSignal,
): Promise<{ events: EarthquakeEvent[]; generatedMs: number; title: string }> {
  let response: Response;
  try {
    response = await fetch(url, { signal });
  } catch (err) {
    if (err instanceof DOMException && err.name === "AbortError") throw err;
    throw new UsgsFetchError("Could not reach the USGS earthquake feed. Check your connection.", err);
  }

  if (!response.ok) {
    throw new UsgsFetchError(`USGS feed responded with ${response.status} ${response.statusText}.`);
  }

  let data: UsgsFeedCollection;
  try {
    data = await response.json();
  } catch (err) {
    throw new UsgsFetchError("USGS feed returned a response that could not be parsed.", err);
  }

  const events = data.features
    .filter((f) => f.geometry && Array.isArray(f.geometry.coordinates))
    .map(normalizeFeature);

  return {
    events,
    generatedMs: data.metadata?.generated ?? Date.now(),
    title: data.metadata?.title ?? "USGS Earthquakes",
  };
}

function normalizeFeature(feature: UsgsFeedCollection["features"][number]): EarthquakeEvent {
  const [longitude, latitude, depthKm] = feature.geometry.coordinates;
  const p = feature.properties;
  return {
    id: feature.id,
    magnitude: typeof p.mag === "number" ? p.mag : null,
    magType: p.magType ?? null,
    place: p.place ?? "Unknown location",
    title: p.title ?? p.place ?? "Unknown event",
    timeMs: p.time,
    updatedMs: p.updated,
    longitude,
    latitude,
    depthKm: typeof depthKm === "number" ? depthKm : null,
    alert: p.alert ?? null,
    status: p.status ?? "automatic",
    tsunami: p.tsunami === 1,
    significance: typeof p.sig === "number" ? p.sig : null,
    felt: typeof p.felt === "number" ? p.felt : null,
    cdi: typeof p.cdi === "number" ? p.cdi : null,
    mmi: typeof p.mmi === "number" ? p.mmi : null,
    type: p.type ?? "earthquake",
    url: p.url,
    detailUrl: p.detail,
    gap: typeof p.gap === "number" ? p.gap : null,
    nst: typeof p.nst === "number" ? p.nst : null,
    dmin: typeof p.dmin === "number" ? p.dmin : null,
    rms: typeof p.rms === "number" ? p.rms : null,
  };
}

import { useEffect, useRef } from "react";
import maplibregl from "maplibre-gl";
import type { GeoJSONSource } from "maplibre-gl";
import type { EarthquakeEvent } from "../types/earthquake";
import { magnitudeToRadius, depthToColor } from "../lib/scales";
import { createTsunamiIcon } from "../lib/tsunamiIcon";
import { formatMagnitude, formatRelativeTime } from "../lib/format";
import { usePrefersReducedMotion } from "../hooks/useNow";

const SOURCE_ID = "quakes";
const CORE_LAYER = "quakes-core";
const ALERT_LAYER = "quakes-alert-ring";
const SELECTED_LAYER = "quakes-selected-ring";
const TSUNAMI_LAYER = "quakes-tsunami";

const STYLE: maplibregl.StyleSpecification = {
  version: 8,
  glyphs: undefined,
  sources: {
    basemap: {
      type: "raster",
      tiles: [
        "https://a.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}@2x.png",
        "https://b.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}@2x.png",
        "https://c.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}@2x.png",
      ],
      tileSize: 256,
      attribution:
        '© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors © <a href="https://carto.com/attributions">CARTO</a>',
    },
  },
  layers: [
    { id: "basemap", type: "raster", source: "basemap", paint: { "raster-opacity": 1, "raster-brightness-min": 0.05 } },
  ],
};

function toFeatureCollection(events: EarthquakeEvent[], selectedId: string | null, hoveredId: string | null, windowIds: Set<string> | null) {
  return {
    type: "FeatureCollection" as const,
    features: events.map((e) => ({
      type: "Feature" as const,
      id: e.id,
      properties: {
        id: e.id,
        radius: magnitudeToRadius(e.magnitude),
        color: depthToColor(e.depthKm),
        alert: e.alert,
        tsunami: e.tsunami,
        selected: e.id === selectedId,
        hovered: e.id === hoveredId,
        inWindow: windowIds ? windowIds.has(e.id) : true,
        label: `M${formatMagnitude(e.magnitude)} — ${e.place}`,
        magnitude: e.magnitude,
        time: e.timeMs,
      },
      geometry: { type: "Point" as const, coordinates: [e.longitude, e.latitude] },
    })),
  };
}

export interface MapViewProps {
  events: EarthquakeEvent[];
  selectedId: string | null;
  hoveredId: string | null;
  windowIds: Set<string> | null;
  onSelect: (id: string) => void;
  onHover: (id: string | null) => void;
  flyToToken: number;
  flyToTarget: { lat: number; lon: number; zoom?: number } | null;
}

export function MapView({ events, selectedId, hoveredId, windowIds, onSelect, onHover, flyToToken, flyToTarget }: MapViewProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<maplibregl.Map | null>(null);
  const readyRef = useRef(false);
  const popupRef = useRef<maplibregl.Popup | null>(null);
  const reducedMotion = usePrefersReducedMotion();
  const eventsRef = useRef(events);
  eventsRef.current = events;

  useEffect(() => {
    if (!containerRef.current) return;
    const map = new maplibregl.Map({
      container: containerRef.current,
      style: STYLE,
      center: [10, 20],
      zoom: 1.4,
      minZoom: 0.6,
      maxZoom: 12,
      attributionControl: { compact: true },
    });
    mapRef.current = map;
    map.addControl(new maplibregl.NavigationControl({ showCompass: false }), "top-right");

    popupRef.current = new maplibregl.Popup({ closeButton: false, closeOnClick: false, offset: 14, maxWidth: "240px" });

    map.on("load", () => {
      map.addImage("tsunami-icon", createTsunamiIcon());
      map.addSource(SOURCE_ID, {
        type: "geojson",
        data: toFeatureCollection(eventsRef.current, null, null, null),
      });

      map.addLayer({
        id: CORE_LAYER,
        type: "circle",
        source: SOURCE_ID,
        paint: {
          "circle-radius": ["get", "radius"],
          "circle-color": ["get", "color"],
          "circle-opacity": ["case", ["get", "inWindow"], 0.85, 0.18],
          "circle-stroke-width": ["case", ["get", "hovered"], 2.5, 1],
          "circle-stroke-color": ["case", ["get", "hovered"], "#f4f5f8", "#0c0d10"],
          "circle-stroke-opacity": ["case", ["get", "inWindow"], 1, 0.25],
        },
      });

      map.addLayer({
        id: ALERT_LAYER,
        type: "circle",
        source: SOURCE_ID,
        filter: ["!=", ["get", "alert"], null],
        paint: {
          "circle-radius": ["+", ["get", "radius"], 5],
          "circle-color": "rgba(0,0,0,0)",
          "circle-stroke-width": 2.5,
          "circle-stroke-color": [
            "match",
            ["get", "alert"],
            "green",
            "#4f9d69",
            "yellow",
            "#d9b02a",
            "orange",
            "#d9791f",
            "red",
            "#c94c3f",
            "#9298ab",
          ],
          "circle-stroke-opacity": ["case", ["get", "inWindow"], 0.95, 0.2],
        },
      });

      map.addLayer({
        id: SELECTED_LAYER,
        type: "circle",
        source: SOURCE_ID,
        filter: ["==", ["get", "selected"], true],
        paint: {
          "circle-radius": ["+", ["get", "radius"], 9],
          "circle-color": "rgba(0,0,0,0)",
          "circle-stroke-width": 2.5,
          "circle-stroke-color": "#f4f5f8",
        },
      });

      map.addLayer({
        id: TSUNAMI_LAYER,
        type: "symbol",
        source: SOURCE_ID,
        filter: ["==", ["get", "tsunami"], true],
        layout: {
          "icon-image": "tsunami-icon",
          "icon-size": 0.85,
          "icon-offset": [0, -1.4],
          "icon-allow-overlap": true,
        },
        paint: { "icon-opacity": ["case", ["get", "inWindow"], 1, 0.25] },
      });

      readyRef.current = true;

      const onClick = (e: maplibregl.MapMouseEvent) => {
        const features = map.queryRenderedFeatures(e.point, { layers: [CORE_LAYER] });
        if (features.length > 0 && features[0].properties?.id) {
          onSelect(String(features[0].properties.id));
        }
      };
      const onMove = (e: maplibregl.MapMouseEvent) => {
        const features = map.queryRenderedFeatures(e.point, { layers: [CORE_LAYER] });
        map.getCanvas().style.cursor = features.length > 0 ? "pointer" : "";
        if (features.length > 0) {
          const f = features[0];
          const id = String(f.properties?.id ?? "");
          onHover(id);
          const coords = (f.geometry as GeoJSON.Point).coordinates.slice() as [number, number];
          const mag = f.properties?.magnitude;
          const label = f.properties?.label ?? "";
          const time = Number(f.properties?.time ?? 0);
          popupRef.current
            ?.setLngLat(coords)
            .setHTML(
              `<div style="font:600 12px/1.3 var(--font-sans,sans-serif);">M${mag ?? "—"}</div><div style="font-size:11.5px;opacity:0.85;margin-top:2px;max-width:200px;">${label}</div><div style="font-size:10.5px;opacity:0.6;margin-top:3px;">${time ? formatRelativeTime(time, Date.now()) : ""}</div>`,
            )
            .addTo(map);
        } else {
          onHover(null);
          popupRef.current?.remove();
        }
      };
      const onLeave = () => {
        onHover(null);
        popupRef.current?.remove();
        map.getCanvas().style.cursor = "";
      };

      map.on("click", onClick);
      map.on("mousemove", onMove);
      map.on("mouseout", onLeave);
    });

    return () => {
      popupRef.current?.remove();
      map.remove();
      mapRef.current = null;
      readyRef.current = false;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    const map = mapRef.current;
    if (!map || !readyRef.current) return;
    const source = map.getSource(SOURCE_ID) as GeoJSONSource | undefined;
    source?.setData(toFeatureCollection(events, selectedId, hoveredId, windowIds));
  }, [events, selectedId, hoveredId, windowIds]);

  useEffect(() => {
    const map = mapRef.current;
    if (!map || !flyToTarget) return;
    map.flyTo({
      center: [flyToTarget.lon, flyToTarget.lat],
      zoom: flyToTarget.zoom ?? Math.max(map.getZoom(), 4),
      duration: reducedMotion ? 0 : 900,
      essential: true,
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [flyToToken]);

  return (
    <div className="relative h-full w-full">
      <div ref={containerRef} role="img" aria-label="World map showing earthquake locations. Use the event list for a keyboard-accessible, non-map view of the same data." className="h-full w-full" />
    </div>
  );
}

